def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize the grid with the number of rows and columns
    grid = [[0] * N for _ in range(M)]

    # Loop through each chatting pair and mark the positions in the grid
    for pair in chatting_pairs:
        grid[pair[0] - 1][pair[1] - 1] += 1
        grid[pair[2] - 1][pair[3] - 1] += 1

    # Initialize the optimal row and column indices for the aisles
    optimal_rows = []
    optimal_cols = []

    # Loop through each row and column and count the number of chatting pairs that can be separated
    for i in range(M):
        for j in range(N):
            if grid[i][j] == 0:
                continue
            # Count the number of chatting pairs that can be separated by adding an aisle in this position
            count = 0
            for pair in chatting_pairs:
                if grid[pair[0] - 1][pair[1] - 1] == 0 or grid[pair[2] - 1][pair[3] - 1] == 0:
                    continue
                if abs(pair[0] - i) + abs(pair[1] - j) == 1 or abs(pair[2] - i) + abs(pair[3] - j) == 1:
                    count += 1
            # If the count is greater than the current maximum, update the optimal row and column indices
            if count > max(optimal_rows):
                optimal_rows = [i]
                optimal_cols = [j]
            elif count == max(optimal_rows):
                optimal_rows.append(i)
                optimal_cols.append(j)

    # Return the optimal row and column indices for the aisles
    return " ".join(str(i + 1) for i in optimal_rows), " ".join(str(j + 1) for j in optimal_cols)
